# RUN: llvm-mc -triple=powerpc-unknown-eabi -mcpu=e200z4 -mattr=+vle -show-encoding %s \
# RUN:   | FileCheck %s
# Expected encodings come from NXP GNU as 2.28 (-mvle -me200z4), generated by
# plans/e200/tools/gen_mc_test.py.
# M-form rotates (VLEPEM Rev. 0 Figure A-14).

# CHECK: e_rlwimi 3, 4, 1, 0, 31 # encoding: [0x74,0x83,0x08,0x3e]
e_rlwimi 3, 4, 1, 0, 31
# CHECK: e_rlwinm 3, 4, 1, 0, 31 # encoding: [0x74,0x83,0x08,0x3f]
e_rlwinm 3, 4, 1, 0, 31
# CHECK: e_rlwinm 3, 4, 31, 31, 0 # encoding: [0x74,0x83,0xff,0xc1]
e_rlwinm 3, 4, 31, 31, 0
